// Ring Sort levels: 60 committed, solver-verified levels (see level-data.ts, generated by
// tools/generate-levels.ts). Nothing is generated at runtime.
import { LEVEL_DATA } from "./level-data";
import type { RingLevel } from "./logic";

export const LEVEL_COUNT = LEVEL_DATA.length;

export const WORLDS = [
  { name: "Sunny Meadow", from: 1 },
  { name: "Copper Hills", from: 11 },
  { name: "Mystery Mine", from: 21 },
  { name: "Locksmith Row", from: 31 },
  { name: "Crystal Falls", from: 41 },
  { name: "Grand Hall", from: 51 },
];

/** Banner shown on the level where a mechanic first appears (0-based index). */
export const INTROS: Record<number, string> = {
  0: "Tap a peg to lift its rings, tap another to drop them (or drag)",
  10: "New: pegs come in different heights",
  20: "New: rings marked ? are hidden until uncovered",
  30: "New: a locked peg opens when its colour is complete",
  40: "Twists combine from here on",
  50: "Grand Hall: tight space, every twist",
};

function clampIndex(index: number): number {
  return Math.max(0, Math.min(LEVEL_COUNT - 1, index));
}

export function getLevel(index: number): RingLevel {
  const r = LEVEL_DATA[clampIndex(index)]!;
  return {
    pegs: r.pegs.map((p) => p.split("").map(Number)),
    caps: [...r.caps],
    hidden: [...r.hidden],
    locks: [...r.locks],
  };
}

export function getPar(index: number): number {
  return LEVEL_DATA[clampIndex(index)]!.par;
}

export function getSolution(index: number): Array<{ from: number; to: number }> {
  return LEVEL_DATA[clampIndex(index)]!.solution.split(" ").map((t) => {
    const [a, b] = t.split(">");
    return { from: Number(a), to: Number(b) };
  });
}

export function hasHidden(index: number): boolean {
  return LEVEL_DATA[clampIndex(index)]!.hidden.some((h) => h > 0);
}

/** Moves allowed for 3 stars and for 2 stars; anything else solved is 1 star. */
export function starLimits(index: number): { three: number; two: number } {
  const par = getPar(index);
  const slack = hasHidden(index) ? 2 : 0;
  return {
    three: par + Math.max(1, Math.floor(par * 0.25)) + slack,
    two: par + Math.max(3, Math.floor(par * 0.75)) + slack,
  };
}

export function starsFor(index: number, moves: number): number {
  const l = starLimits(index);
  return moves <= l.three ? 3 : moves <= l.two ? 2 : 1;
}
